Object.assign(fullGuideLocales.hi,{
varroa:article('Varroa प्रबंधन का क्रम है: मापें, उपाय चुनें और परिणाम जाँचें। उपचार का रिकॉर्ड उपयोगी है, लेकिन बाद की स्थिति का आकलन निगरानी से करें।',[
 ['तुलना योग्य अवलोकन','विधि, नमूने का आकार और माइट संख्या दर्ज करें। परिणाम समझते समय विधि और ब्रूड की स्थिति देखें। एक नमूने में शून्य माइट होने से अनुपस्थिति सिद्ध नहीं होती। निर्णय सीमा स्थानीय परिस्थितियों पर निर्भर है; एक वैश्विक संख्या सही नहीं है।'],
 ['उपाय चुनना','निगरानी के साथ उपयुक्त कॉलोनी प्रबंधन अपनाएँ। उत्पाद का स्थानीय पंजीकरण, तापमान, ब्रूड और शहद सुपर की पाबंदियाँ जाँचें। केवल सक्रिय तत्व के नाम के बजाय वर्तमान उत्पाद लेबल देखें।']
],[['आँकड़े बिगड़ रहे हैं','नमूनों की तुलनीयता और योजना जाँचें। बदलाव पर स्थानीय विशेषज्ञ से चर्चा करें।'],['उपचार पूरा हुआ','चुनी योजना के अनुसार फिर निगरानी करें। जाँच बिना कॉलोनी को माइट-मुक्त न लिखें।']],['विधि और नमूना आकार','माइट संख्या और कॉलोनी स्थिति','उत्पाद, लेबल और तारीख','बाद की जाँच का परिणाम'],[['नकारात्मक नमूने का अर्थ Varroa नहीं है?','नहीं। नमूना स्थिति का केवल एक भाग दिखाता है, विशेषकर ब्रूड होने पर।'],['क्या सभी छत्तों की एक योजना हो?','स्थितियाँ अलग हो सकती हैं। हर छत्ते का अलग रिकॉर्ड रखें।']]),
oxalic:article('सिर्फ ऑक्सैलिक अम्ल का नाम उपयुक्त उत्पाद, खुराक या कैलेंडर तय नहीं करता। पहले परिस्थितियाँ और वर्तमान लेबल दर्ज करें। CybBee मिश्रण नहीं गणना करता और दोहराए उपचार नहीं निर्धारित करता।',[
 ['परिस्थितियों के अनुसार निर्णय','देश, पंजीकृत उत्पाद का व्यापारिक नाम और विधि लिखें। ब्रूड, शहद सुपर, तापमान और कॉलोनी की पाबंदियाँ जाँचें। अमेरिका या ब्रिटेन का लेबल दूसरे देश में अनुमति नहीं देता।'],
 ['तैयारी और रिकॉर्ड','उपकरण, संचालक सुरक्षा और उपयोग के लेबल निर्देश मानें। पहले निर्णय का आधार बनी निगरानी लिखें। बाद में वास्तविक तारीख, उत्पाद और प्रभाव की अगली जाँच लिखें। कार्रवाई और परिणाम अलग रखें।']
],[['पंजीकृत उत्पाद का वर्तमान लेबल नहीं है','चैट की सलाह से उपचार योजना न बनाएँ। पहले वर्तमान दस्तावेज़ और उसकी उपयोगिता जाँचें।'],['ब्रूड या शहद सुपर हैं','अपने उत्पाद और विधि की पाबंदियाँ देखें। दूसरे उत्पाद की अनुमति लागू नहीं होती।']],['देश और उत्पाद','वर्तमान लेबल का HTTPS लिंक','विधि और कॉलोनी की परिस्थितियाँ','उपकरण और सुरक्षा आवश्यकताएँ','वास्तविक उपयोग और अनुवर्ती जाँच'],[['सार्वभौमिक खुराक क्यों नहीं है?','उत्पाद, विधियाँ और पंजीकरण अलग हैं। गलती कॉलोनी या संचालक को नुकसान पहुँचा सकती है।'],['कब दोहराएँ?','केवल वर्तमान लेबल और निगरानी योजना के अनुसार, सामान्य ऐप कैलेंडर से नहीं।']]),
queen:article('नई रानी देना एक प्रक्रिया है, केवल पिंजरा खोलना नहीं। कॉलोनी की स्थिति और उस रानी के लिए सही प्रोटोकॉल तय करें। संदेह हो तो रानी खोने से पहले स्थिति स्पष्ट करें।',[
 ['रानी देने से पहले','बदलाव का कारण, रानी का स्रोत, मिलने की तारीख और आपूर्तिकर्ता की जानकारी लिखें। पुरानी रानी की अनुपस्थिति की पुष्टि तथा अंडे और रानी कोशिकाओं का ज्ञान अलग दर्ज करें। कुंवारी, मेटेड और कृत्रिम गर्भाधान वाली रानियों को अलग तरीके लग सकते हैं।'],
 ['परिणाम जाँचें','आपूर्तिकर्ता के निर्देश और चुने प्रोटोकॉल का पालन करें। स्वीकृति और अंडे देने की पुष्टि की योजना बनाएँ। छोड़ देना स्वीकृति का प्रमाण नहीं है। देने और परिणाम की पुष्टि की तारीख अलग रखें।']
],[['रानी न होने पर यकीन नहीं','बिना जाँच बदलाव न करें। संकेत स्पष्ट करें और अनुभवी मार्गदर्शक से मदद लें।'],['रानी छोड़ी गई, परिणाम अज्ञात','पुष्टि लंबित लिखें। अगली जाँच प्रोटोकॉल से तय करें, रोज़ की सूचना से नहीं।']],['कारण और कॉलोनी स्थिति','रानी का प्रकार, स्रोत और वर्ष','आपूर्तिकर्ता का प्रोटोकॉल','देने और अलग परिणाम तारीख'],[['हर रानी को एक ही समय बाद छोड़ें?','नहीं। परिस्थितियाँ जाँचे बिना दूसरे की समय-सारणी न अपनाएँ।'],['क्या AI छोड़ने का निर्णय ले सकता है?','AI प्रश्न बनाने में मदद कर सकता है, लेकिन कॉलोनी नहीं देखता और स्वीकृति प्रमाणित नहीं करता।']])
});
Object.assign(fullGuideLocales.es,{
varroa:article('La gestión de Varroa sigue el ciclo medir, elegir una medida y comprobar el resultado. Registrar el tratamiento ayuda, pero el seguimiento permite evaluar qué ocurrió después.',[
 ['Observaciones comparables','Anote método, tamaño de muestra y ácaros. Interprete según método y cría. Cero ácaros en una muestra no demuestra ausencia. El umbral de decisión depende del contexto local; una cifra mundial no es adecuada.'],
 ['Elegir medidas','Combine seguimiento y manejo apropiado. Compruebe registro local, temperatura, cría y restricciones de alzas melarias. Consulte la etiqueta vigente, no solo el nombre del principio activo.']
],[['Los indicadores empeoran','Compruebe que las muestras sean comparables y revise el plan con un especialista local.'],['El tratamiento ha terminado','Programe otro control según el protocolo. No declare la colonia libre de ácaros sin comprobarlo.']],['Método y tamaño de muestra','Ácaros y condición de la colonia','Producto, etiqueta y fecha','Resultado posterior'],[['¿Una muestra negativa significa ausencia de Varroa?','No. Representa solo parte de la situación, especialmente con cría.'],['¿Un mismo plan para todas las colmenas?','Las condiciones pueden variar. Lleve registros por colmena.']]),
oxalic:article('El nombre ácido oxálico no determina por sí solo producto, dosis ni calendario apropiados. Registre condiciones y etiqueta vigente. CybBee no calcula mezclas ni prescribe repeticiones.',[
 ['Decidir según las condiciones','Anote país, nombre comercial del producto registrado y método. Revise restricciones de cría, alzas melarias, temperatura y colonia. Una etiqueta estadounidense o británica no autoriza el uso en otro país.'],
 ['Preparación y registro','Siga los requisitos de equipo, protección del operario y aplicación. Antes, anote el seguimiento que justifica la decisión. Después, fecha real, producto y control de eficacia previsto. Separe acción y resultado.']
],[['Falta la etiqueta vigente del producto registrado','No construya un protocolo con consejos de chat. Busque el documento actual y compruebe su aplicabilidad.'],['Hay cría o alzas melarias','Revise las restricciones de su producto y método exactos; no sustituya una autorización de otro producto.']],['País y producto','Enlace HTTPS a la etiqueta vigente','Método y condiciones de la colonia','Equipo y protección','Aplicación real y seguimiento'],[['¿Por qué no hay dosis universal?','Productos, métodos y registros difieren. Un error puede dañar a la colonia o al operario.'],['¿Cuándo repetir?','Solo según la etiqueta vigente y el plan de control, no el calendario general de la aplicación.']]),
queen:article('Introducir una reina es un proceso, no simplemente abrir la jaula. Determine el estado de la colonia y el protocolo adecuado para esa reina. Ante la duda, aclare la situación antes de arriesgarla.',[
 ['Antes de introducirla','Anote motivo del cambio, origen, fecha de recepción e información del proveedor. Registre por separado si se confirmó la ausencia de la reina anterior y qué sabe sobre huevos y realeras. Reinas vírgenes, fecundadas o inseminadas instrumentalmente pueden necesitar enfoques diferentes.'],
 ['Comprobar el resultado','Siga las instrucciones del proveedor y el protocolo elegido. Programe observación de aceptación y confirmación de puesta. La liberación no demuestra aceptación. Separe fecha de introducción y de resultado confirmado.']
],[['No sabe si la colonia está huérfana','No cambie la reina a ciegas. Aclare los signos y solicite un mentor experimentado.'],['Reina liberada, resultado desconocido','Marque confirmación pendiente. Fije la siguiente inspección por protocolo, no por una notificación diaria.']],['Motivo y estado de la colonia','Tipo, origen y año de la reina','Protocolo del proveedor','Introducción y fecha separada de resultado'],[['¿Un intervalo de liberación sirve para todas?','No. No copie plazos ajenos sin comprobar las condiciones.'],['¿Puede decidir la IA cuándo liberarla?','Puede ayudar a plantear preguntas, pero no inspecciona su colonia ni confirma aceptación.']])
});
Object.assign(fullGuideLocales.ar,{
varroa:article('تتبع إدارة الفاروا دورة القياس ثم اختيار إجراء ثم التحقّق من النتيجة. سجل المعالجة مفيد، لكن الرصد يساعد في تقييم ما حدث بعدها.',[
 ['ملاحظات قابلة للمقارنة','دوّن الطريقة وحجم العينة وعدد الحلم، وفسّر النتائج بحسب الطريقة والحضنة. صفر في عينة واحدة لا يثبت الغياب. عتبة القرار تعتمد على الظروف المحلية؛ لا يصلح رقم واحد للعالم كله.'],
 ['اختيار الإجراءات','اجمع الرصد مع إدارة مناسبة للطائفة. تحقّق من التسجيل المحلي والحرارة والحضنة وقيود عاسلات العسل. اقرأ ملصق المنتج الحالي، لا اسم المادة الفعالة فقط.']
],[['المؤشرات تتدهور','راجع قابلية مقارنة العينات والخطة، وناقش التعديل مع مختص محلي.'],['انتهت المعالجة','خطط لرصد لاحق وفق البروتوكول. لا تسجّل الطائفة خالية من الحلم دون تحقّق.']],['الطريقة وحجم العينة','عدد الحلم وحالة الطائفة','المنتج والملصق والتاريخ','نتيجة المتابعة'],[['هل العينة السلبية تعني عدم وجود فاروا؟','لا. العينة تمثل جزءاً من الوضع، خصوصاً مع وجود الحضنة.'],['هل تحتاج كل الخلايا إلى خطة واحدة؟','قد تختلف حالاتها؛ احتفظ بسجل لكل خلية.']]),
oxalic:article('اسم حمض الأكساليك وحده لا يحدّد منتجاً أو جرعة أو جدولاً مناسباً. سجّل الظروف والملصق الحالي أولاً. لا يحسب CybBee الخلطات ولا يصف تكرار المعالجة.',[
 ['القرار حسب الظروف','سجّل البلد والاسم التجاري للمنتج المسجّل والطريقة. راجع قيود الحضنة والعاسلات والحرارة وحالة الطائفة. ملصق أمريكي أو بريطاني لا يجيز الاستخدام في بلد آخر.'],
 ['التحضير والتسجيل','اتبع متطلبات الملصق للمعدات وحماية المشغّل والتطبيق. سجّل مسبقاً الرصد الذي يدعم القرار. وبعد التطبيق سجّل التاريخ الفعلي والمنتج وخطة اختبار الفعالية. افصل الإجراء عن نتيجته.']
],[['لا يوجد ملصق حالي لمنتج مسجّل','لا تبنِ برنامج معالجة على نصيحة دردشة. ابحث عن الوثيقة الحالية وتحقّق من انطباقها.'],['توجد حضنة أو عاسلات','راجع قيود منتجك وطريقتك تحديداً؛ لا تستبدلها بترخيص منتج آخر.']],['البلد والمنتج','رابط HTTPS للملصق الحالي','الطريقة وظروف الطائفة','المعدات والحماية','التطبيق الفعلي والمتابعة'],[['لماذا لا توجد جرعة عامة؟','تختلف المنتجات والطرق والتسجيلات؛ والخطأ قد يؤذي الطائفة أو المشغّل.'],['متى تُكرّر؟','فقط وفق الملصق الحالي وخطة الرصد، لا التقويم العام للتطبيق.']]),
queen:article('إدخال ملكة عملية وليس مجرد فتح القفص. حدّد حالة الطائفة والبروتوكول الملائم لهذه الملكة. عند الشك، وضّح الوضع قبل المخاطرة بفقدها.',[
 ['قبل الإدخال','سجّل سبب الاستبدال ومصدر الملكة وتاريخ الاستلام ومعلومات المورّد. دوّن منفصلاً هل تأكّد غياب الملكة السابقة، وما المعروف عن البيض والبيوت الملكية. الملكات العذارى والملقّحة والملقّحة آلياً قد تحتاج مناهج مختلفة.'],
 ['التحقّق من النتيجة','اتبع تعليمات المورّد والبروتوكول المختار. خطط لملاحظة القبول وتأكيد وضع البيض. إطلاق الملكة لا يثبت قبولها. افصل تاريخ الإدخال عن تاريخ تأكيد النتيجة.']
],[['لست متأكداً من غياب الملكة','لا تستبدلها دون تحقّق. وضّح العلامات واستعن بمرشد خبير.'],['أُطلقت الملكة والنتيجة مجهولة','دوّن أن التأكيد معلّق. حدّد الفحص التالي وفق البروتوكول، لا إشعار يومي.']],['السبب وحالة الطائفة','نوع الملكة ومصدرها وسنتها','بروتوكول المورّد','تاريخ الإدخال وتاريخ منفصل للنتيجة'],[['هل يناسب موعد إطلاق واحد جميع الملكات؟','لا. لا تنقل توقيت شخص آخر دون فحص الظروف.'],['هل يقرّر الذكاء الاصطناعي موعد الإطلاق؟','يساعد في صياغة الأسئلة، لكنه لا يفحص الطائفة ولا يؤكد القبول.']])
});
Object.assign(fullGuideLocales.pt,{
varroa:article('O manejo de Varroa segue medir, escolher uma medida e verificar o resultado. O registro do tratamento é útil, mas o monitoramento permite avaliar o que ocorreu depois.',[
 ['Observações comparáveis','Registre método, tamanho da amostra e ácaros. Interprete conforme método e cria. Zero ácaros em uma amostra não comprova ausência. Limites de decisão dependem das condições locais; um número mundial não é adequado.'],
 ['Escolher medidas','Combine monitoramento e manejo apropriado. Confira registro local, temperatura, cria e restrições das melgueiras. Consulte o rótulo atual, não apenas o nome do princípio ativo.']
],[['Os indicadores pioram','Confira a comparabilidade das amostras e o plano. Discuta mudanças com um especialista local.'],['O tratamento terminou','Programe novo monitoramento conforme o protocolo. Não marque a colônia como livre de ácaros sem verificar.']],['Método e tamanho da amostra','Ácaros e condição da colônia','Produto, rótulo e data','Resultado posterior'],[['Amostra negativa significa ausência de Varroa?','Não. Representa apenas parte da situação, especialmente com cria.'],['Um plano igual para todas as colmeias?','As condições podem variar. Mantenha registros por colmeia.']]),
oxalic:article('O nome ácido oxálico não define sozinho produto, dose ou calendário adequados. Registre condições e rótulo atual primeiro. CybBee não calcula misturas nem prescreve repetições.',[
 ['Decisão conforme as condições','Registre país, nome comercial do produto registrado e método. Confira restrições de cria, melgueiras, temperatura e colônia. Um rótulo dos EUA ou Reino Unido não autoriza uso em outro país.'],
 ['Preparação e registro','Siga os requisitos de equipamento, proteção do aplicador e aplicação do rótulo. Antes, registre o monitoramento que fundamenta a decisão. Depois, data real, produto e verificação de eficácia planejada. Separe ação e resultado.']
],[['Falta o rótulo atual do produto registrado','Não monte um tratamento com conselho de chat. Encontre o documento atual e confirme sua aplicabilidade.'],['Há cria ou melgueiras','Confira as restrições do produto e método exatos; não substitua uma autorização de outro produto.']],['País e produto','Link HTTPS para o rótulo atual','Método e condições da colônia','Equipamento e proteção','Aplicação real e acompanhamento'],[['Por que não há dose universal?','Produtos, métodos e registros diferem. Um erro pode prejudicar a colônia ou o aplicador.'],['Quando repetir?','Somente conforme o rótulo atual e o plano de monitoramento, não pelo calendário geral do app.']]),
queen:article('Introduzir uma rainha é um processo, não apenas abrir a gaiola. Determine a condição da colônia e o protocolo adequado àquela rainha. Na dúvida, esclareça a situação antes de arriscá-la.',[
 ['Antes da introdução','Registre motivo da troca, origem, data de recebimento e informações do fornecedor. Anote separadamente se a ausência da rainha anterior foi confirmada e o que se sabe sobre ovos e realeiras. Rainhas virgens, fecundadas ou inseminadas instrumentalmente podem exigir abordagens diferentes.'],
 ['Verificar o resultado','Siga as instruções do fornecedor e o protocolo escolhido. Planeje observações de aceitação e confirmação da postura. A liberação não comprova aceitação. Separe a data de introdução da data de resultado confirmado.']
],[['Não sabe se a colônia está órfã','Não substitua às cegas. Esclareça os sinais e procure um mentor experiente.'],['Rainha liberada, resultado desconhecido','Marque confirmação pendente. Agende a próxima inspeção pelo protocolo, não por uma notificação diária.']],['Motivo e condição da colônia','Tipo, origem e ano da rainha','Protocolo do fornecedor','Introdução e data separada de resultado'],[['Um intervalo de liberação serve para todas?','Não. Não copie prazos de outros sem verificar as condições.'],['A IA pode decidir quando liberar?','Pode ajudar a formular perguntas, mas não examina a colônia nem confirma aceitação.']])
});
Object.assign(fullGuideLocales.bn,{
varroa:article('Varroa ব্যবস্থাপনার ধাপ হলো মাপা, ব্যবস্থা বেছে নেওয়া এবং ফল যাচাই। চিকিৎসার রেকর্ড উপকারী, কিন্তু পরে কী হয়েছে তা বুঝতে পর্যবেক্ষণ দরকার।',[
 ['তুলনাযোগ্য পর্যবেক্ষণ','পদ্ধতি, নমুনার আকার ও মাইটের সংখ্যা লিখুন। পদ্ধতি ও ব্রুডের অবস্থা অনুযায়ী ফল বুঝুন। একটি নমুনায় শূন্য মানে মাইট নেই নয়। সিদ্ধান্তের সীমা স্থানীয় পরিস্থিতির ওপর নির্ভর করে; সারা বিশ্বের জন্য এক সংখ্যা ঠিক নয়।'],
 ['ব্যবস্থা বেছে নেওয়া','পর্যবেক্ষণের সঙ্গে উপযুক্ত কলোনি ব্যবস্থাপনা মিলিয়ে নিন। স্থানীয় নিবন্ধন, তাপমাত্রা, ব্রুড ও মধু সুপারের বিধিনিষেধ দেখুন। শুধু সক্রিয় উপাদানের নাম নয়, বর্তমান পণ্য-লেবেল পড়ুন।']
],[['সূচক খারাপ হচ্ছে','নমুনার তুলনাযোগ্যতা ও পরিকল্পনা দেখুন। পরিবর্তন নিয়ে স্থানীয় বিশেষজ্ঞের সঙ্গে আলোচনা করুন।'],['চিকিৎসা শেষ','নির্বাচিত পদ্ধতি অনুযায়ী আবার পর্যবেক্ষণ করুন। যাচাই ছাড়া কলোনিকে মাইটমুক্ত লিখবেন না।']],['পদ্ধতি ও নমুনার আকার','মাইটের সংখ্যা ও কলোনির অবস্থা','পণ্য, লেবেল ও তারিখ','পরবর্তী পরীক্ষার ফল'],[['নেতিবাচক নমুনা কি Varroa নেই বোঝায়?','না। নমুনা পরিস্থিতির শুধু অংশ দেখায়, বিশেষ করে ব্রুড থাকলে।'],['সব বাক্সে কি একই পরিকল্পনা?','অবস্থা আলাদা হতে পারে। প্রতি বাক্সে পৃথক রেকর্ড রাখুন।']]),
oxalic:article('অক্সালিক অ্যাসিড নামটিই উপযুক্ত পণ্য, মাত্রা বা সময়সূচি ঠিক করে না। আগে পরিস্থিতি ও বর্তমান লেবেল লিখুন। CybBee মিশ্রণ গণনা বা পুনরায় চিকিৎসা নির্ধারণ করে না।',[
 ['পরিস্থিতি অনুযায়ী সিদ্ধান্ত','দেশ, নিবন্ধিত পণ্যের বাণিজ্যিক নাম ও পদ্ধতি লিখুন। ব্রুড, মধু সুপার, তাপমাত্রা ও কলোনির বিধিনিষেধ দেখুন। যুক্তরাষ্ট্র বা যুক্তরাজ্যের লেবেল অন্য দেশে ব্যবহারের অনুমতি নয়।'],
 ['প্রস্তুতি ও রেকর্ড','যন্ত্র, ব্যবহারকারীর সুরক্ষা ও প্রয়োগের লেবেল নির্দেশ মানুন। আগে সিদ্ধান্তের ভিত্তি হওয়া পর্যবেক্ষণ লিখুন। পরে প্রকৃত তারিখ, পণ্য ও কার্যকারিতা যাচাইয়ের পরিকল্পনা লিখুন। কাজ ও ফল আলাদা রাখুন।']
],[['নিবন্ধিত পণ্যের বর্তমান লেবেল নেই','চ্যাটের পরামর্শ দিয়ে চিকিৎসা পরিকল্পনা বানাবেন না। আগে বর্তমান নথি ও প্রযোজ্যতা যাচাই করুন।'],['ব্রুড বা মধু সুপার আছে','নিজের নির্দিষ্ট পণ্য ও পদ্ধতির বিধিনিষেধ দেখুন; অন্য পণ্যের অনুমতি ব্যবহার করবেন না।']],['দেশ ও পণ্য','বর্তমান লেবেলের HTTPS লিংক','পদ্ধতি ও কলোনির পরিস্থিতি','যন্ত্র ও সুরক্ষার প্রয়োজন','প্রকৃত প্রয়োগ ও পরবর্তী পরীক্ষা'],[['সার্বজনীন মাত্রা নেই কেন?','পণ্য, পদ্ধতি ও নিবন্ধন আলাদা। ভুলে কলোনি বা ব্যবহারকারীর ক্ষতি হতে পারে।'],['কখন আবার প্রয়োগ?','শুধু বর্তমান লেবেল ও পর্যবেক্ষণ পরিকল্পনা অনুযায়ী, অ্যাপের সাধারণ ক্যালেন্ডার দেখে নয়।']]),
queen:article('নতুন রানি দেওয়া একটি প্রক্রিয়া, শুধু খাঁচা খোলা নয়। কলোনির অবস্থা ও ওই রানির উপযুক্ত পদ্ধতি ঠিক করুন। সন্দেহ হলে রানি হারানোর আগে পরিস্থিতি স্পষ্ট করুন।',[
 ['রানি দেওয়ার আগে','বদলের কারণ, রানির উৎস, পাওয়ার তারিখ ও সরবরাহকারীর তথ্য লিখুন। আগের রানির অনুপস্থিতি নিশ্চিত কি না এবং ডিম ও রানি কোষের তথ্য আলাদা রাখুন। কুমারী, মিলিত ও যন্ত্রের মাধ্যমে প্রজনিত রানির জন্য আলাদা পদ্ধতি লাগতে পারে।'],
 ['ফল যাচাই','সরবরাহকারীর নির্দেশ ও নির্বাচিত পদ্ধতি অনুসরণ করুন। গ্রহণ ও ডিম দেওয়ার নিশ্চয়তা দেখার পরিকল্পনা করুন। ছেড়ে দেওয়া গ্রহণের প্রমাণ নয়। দেওয়ার তারিখ ও ফল নিশ্চিত করার তারিখ আলাদা লিখুন।']
],[['কলোনি রানিহীন কি না নিশ্চিত নন','অন্ধভাবে বদলাবেন না। লক্ষণ পরিষ্কার করে অভিজ্ঞ ব্যক্তির সহায়তা নিন।'],['রানি ছাড়া হয়েছে, ফল অজানা','নিশ্চিতকরণ বাকি লিখুন। পরের পরীক্ষা পদ্ধতি অনুযায়ী রাখুন, দৈনিক বিজ্ঞপ্তি অনুযায়ী নয়।']],['কারণ ও কলোনির অবস্থা','রানির ধরন, উৎস ও বছর','সরবরাহকারীর পদ্ধতি','দেওয়ার ও আলাদা ফলের তারিখ'],[['সব রানিকে একই সময় পরে ছাড়তে হয়?','না। পরিস্থিতি না দেখে অন্যের সময়সূচি নকল করবেন না।'],['AI কি ছাড়ার সিদ্ধান্ত নিতে পারে?','প্রশ্ন সাজাতে পারে, কিন্তু কলোনি দেখে না এবং গ্রহণ নিশ্চিত করে না।']])
});
Object.assign(fullGuideLocales.fr,{
varroa:article('La gestion de Varroa suit le cycle mesurer, choisir une mesure et vérifier le résultat. Un traitement consigné est utile, mais le suivi permet d’évaluer ce qui s’est passé ensuite.',[
 ['Observations comparables','Notez méthode, taille d’échantillon et nombre d’acariens. Interprétez selon la méthode et le couvain. Zéro dans un échantillon ne prouve pas l’absence. Les seuils dépendent des conditions locales ; un chiffre mondial unique est inadapté.'],
 ['Choisir les mesures','Associez suivi et conduite adaptée. Vérifiez autorisation locale, température, couvain et restrictions des hausses à miel. Consultez la notice actuelle, pas seulement le nom de la substance active.']
],[['Les indicateurs se dégradent','Vérifiez la comparabilité des prélèvements et le plan. Discutez des changements avec un spécialiste local.'],['Le traitement est terminé','Prévoyez un nouveau suivi selon le protocole. Ne déclarez pas la colonie sans acariens sans vérification.']],['Méthode et taille d’échantillon','Acariens et état de la colonie','Produit, notice et date','Résultat du suivi'],[['Un prélèvement négatif signifie-t-il absence de Varroa ?','Non. Il ne représente qu’une partie de la situation, surtout avec du couvain.'],['Un seul plan pour toutes les ruches ?','Leurs états peuvent différer. Gardez un relevé par ruche.']]),
oxalic:article('Le nom acide oxalique ne définit pas à lui seul un produit, une dose ou un calendrier adaptés. Consignez d’abord conditions et notice actuelle. CybBee ne calcule pas de mélanges ni ne prescrit de répétitions.',[
 ['Décider selon les conditions','Notez pays, nom commercial du produit autorisé et méthode. Vérifiez les restrictions de couvain, hausses, température et colonie. Une notice américaine ou britannique n’autorise pas l’usage dans un autre pays.'],
 ['Préparation et relevé','Respectez les exigences de matériel, protection de l’opérateur et application. Avant, consignez le suivi justifiant la décision. Après, notez date réelle, produit et contrôle d’efficacité prévu. Séparez action et résultat.']
],[['Pas de notice actuelle pour un produit autorisé','Ne construisez pas un traitement à partir de conseils de chat. Trouvez le document actuel et vérifiez son applicabilité.'],['Présence de couvain ou de hausses','Vérifiez les restrictions de votre produit et méthode précis ; l’autorisation d’un autre produit ne s’y substitue pas.']],['Pays et produit','Lien HTTPS vers la notice actuelle','Méthode et état de la colonie','Matériel et protection','Application réelle et suivi'],[['Pourquoi pas de dose universelle ?','Produits, méthodes et autorisations diffèrent. Une erreur peut nuire à la colonie ou à l’opérateur.'],['Quand répéter ?','Seulement selon la notice actuelle et le plan de suivi, pas le calendrier général de l’application.']]),
queen:article('Introduire une reine est un processus, pas seulement ouvrir une cage. Établissez l’état de la colonie et le protocole adapté à cette reine. En cas de doute, clarifiez la situation avant de la risquer.',[
 ['Avant l’introduction','Notez motif du remplacement, origine, réception et informations du fournisseur. Consignez séparément si l’absence de l’ancienne reine est confirmée et ce que vous savez des œufs et cellules royales. Reines vierges, fécondées ou inséminées instrumentalement peuvent nécessiter des approches différentes.'],
 ['Vérifier le résultat','Suivez les instructions du fournisseur et le protocole choisi. Prévoyez observation de l’acceptation et confirmation de ponte. La libération ne prouve pas l’acceptation. Séparez date d’introduction et date de résultat confirmé.']
],[['Vous ne savez pas si la colonie est orpheline','Ne remplacez pas à l’aveugle. Clarifiez les signes avec un mentor expérimenté.'],['Reine libérée, résultat inconnu','Notez confirmation en attente. Fixez la prochaine visite selon le protocole, pas une notification quotidienne.']],['Motif et état de la colonie','Type, origine et année de la reine','Protocole du fournisseur','Introduction et date séparée de résultat'],[['Un même délai de libération pour toutes ?','Non. Ne copiez pas les délais d’autrui sans vérifier les conditions.'],['L’IA peut-elle décider de la libération ?','Elle aide à formuler des questions, mais n’examine pas la colonie et ne confirme pas l’acceptation.']])
});
Object.assign(fullGuideLocales.de,{
varroa:article('Varroa-Management folgt dem Ablauf messen, Maßnahme wählen und Ergebnis prüfen. Eine Behandlungsnotiz ist nützlich; Monitoring hilft zu beurteilen, was danach geschah.',[
 ['Vergleichbare Beobachtungen','Notieren Sie Methode, Stichprobengröße und Milbenzahl. Berücksichtigen Sie Methode und Brutstatus. Null Milben in einer Probe beweisen keine Abwesenheit. Entscheidungsschwellen hängen von örtlichen Bedingungen ab; eine Weltzahl ist ungeeignet.'],
 ['Maßnahmen wählen','Verbinden Sie Monitoring und geeignete Völkerführung. Prüfen Sie örtliche Zulassung, Temperatur, Brut und Honigraumauflagen. Nutzen Sie die aktuelle Produktanleitung, nicht nur den Wirkstoffnamen.']
],[['Werte verschlechtern sich','Prüfen Sie Vergleichbarkeit und Plan. Besprechen Sie Änderungen mit einer örtlichen Fachperson.'],['Behandlung abgeschlossen','Planen Sie weitere Kontrollen nach dem Protokoll. Kennzeichnen Sie das Volk nicht ohne Prüfung als milbenfrei.']],['Methode und Stichprobengröße','Milbenzahl und Volkszustand','Produkt, Anleitung und Datum','Ergebnis der Nachkontrolle'],[['Bedeutet eine negative Probe keine Varroa?','Nein. Sie zeigt nur einen Teil der Situation, besonders bei vorhandener Brut.'],['Ein identischer Plan für alle Beuten?','Der Zustand kann unterschiedlich sein. Dokumentieren Sie jedes Volk.']]),
oxalic:article('Der Name Oxalsäure allein bestimmt weder geeignetes Produkt noch Dosis oder Kalender. Halten Sie zuerst Bedingungen und aktuelle Anleitung fest. CybBee berechnet keine Mischungen und verordnet keine Wiederholungen.',[
 ['Nach Bedingungen entscheiden','Notieren Sie Land, Handelsnamen des zugelassenen Produkts und Methode. Prüfen Sie Brut-, Honigraum-, Temperatur- und Volksauflagen. Eine US- oder britische Anleitung erlaubt keine Anwendung in einem anderen Land.'],
 ['Vorbereitung und Dokumentation','Beachten Sie Anforderungen an Geräte, Anwenderschutz und Anwendung. Halten Sie vorher den entscheidungsrelevanten Monitoringbefund fest. Danach dokumentieren Sie tatsächliches Datum, Produkt und geplante Wirkungskontrolle. Trennen Sie Maßnahme und Ergebnis.']
],[['Keine aktuelle Anleitung eines zugelassenen Produkts','Erstellen Sie kein Behandlungsschema aus Chat-Ratschlägen. Finden Sie das aktuelle Dokument und prüfen Sie seine Anwendbarkeit.'],['Brut oder Honigräume vorhanden','Prüfen Sie die Auflagen genau Ihres Produkts und Verfahrens; die Erlaubnis eines anderen Mittels ist kein Ersatz.']],['Land und Produkt','HTTPS-Link zur aktuellen Anleitung','Methode und Volksbedingungen','Geräte- und Schutzanforderungen','Tatsächliche Anwendung und Nachkontrolle'],[['Warum keine allgemeine Dosis?','Produkte, Verfahren und Zulassungen unterscheiden sich. Fehler können Volk oder Anwender schädigen.'],['Wann wiederholen?','Nur gemäß aktueller Anleitung und Monitoringplan, nicht nach dem allgemeinen App-Kalender.']]),
queen:article('Eine Königin zuzusetzen ist ein Prozess, nicht bloß das Öffnen eines Käfigs. Klären Sie Volkszustand und passendes Protokoll für diese Königin. Bei Unsicherheit erst klären, bevor Sie ihren Verlust riskieren.',[
 ['Vor dem Zusetzen','Notieren Sie Austauschgrund, Herkunft, Empfangsdatum und Lieferanteninformationen. Halten Sie getrennt fest, ob die Abwesenheit der alten Königin bestätigt ist und was über Eier und Weiselzellen bekannt ist. Unbegattete, begattete und instrumentell besamte Königinnen können unterschiedliche Vorgehensweisen erfordern.'],
 ['Ergebnis prüfen','Folgen Sie Lieferantenhinweisen und gewähltem Protokoll. Planen Sie Annahmebeobachtung und Bestätigung der Eiablage. Freilassen beweist keine Annahme. Trennen Sie Zusetzdatum und Datum des bestätigten Ergebnisses.']
],[['Unklar, ob das Volk weisellos ist','Tauschen Sie nicht blind. Klären Sie die Anzeichen mit einer erfahrenen Fachperson.'],['Königin freigelassen, Ergebnis unbekannt','Vermerken Sie ausstehende Bestätigung. Planen Sie die nächste Durchsicht nach Protokoll, nicht nach täglicher Meldung.']],['Grund und Volkszustand','Königinnentyp, Herkunft und Jahr','Lieferantenprotokoll','Zusetzen und separates Ergebnisdatum'],[['Passt ein Freilassintervall für alle?','Nein. Übernehmen Sie keine fremden Fristen ohne Prüfung der Bedingungen.'],['Kann KI den Freilasszeitpunkt bestimmen?','Sie hilft Fragen zu formulieren, untersucht Ihr Volk aber nicht und bestätigt keine Annahme.']])
});
